internal static class CustomActionMismatchChecks {
 public static bool Run(string sourceRoot,out string detail) {
  var path=Path.Combine(AppContext.BaseDirectory,"fixtures","custom-action-mismatch-cases.json"); using var doc=JsonDocument.Parse(File.ReadAllText(path)); var r=doc.RootElement; var actual=r.GetProperty("arR33Decision");
  string evidencePath=r.GetProperty("provenancePath").GetString()!; using var actualDoc=JsonDocument.Parse(File.ReadAllText(evidencePath)); bool evidence=TryExtractEvidence(actualDoc.RootElement,actual,out string actualDetail); var negative=r.GetProperty("evidenceNegativeCases").EnumerateArray().ToArray(); bool negatives=negative.Length==3&&negative.Any(x=>x.GetProperty("name").GetString()=="wrong-profile")&&negative.Any(x=>x.GetProperty("name").GetString()=="missing-entry")&&negative.Any(x=>x.GetProperty("name").GetString()=="missing-required-lastShallEndResult")&&!TryExtractEvidence(actualDoc.RootElement,actual,"not-the-qa-profile",actual.GetProperty("botPointerDecimal").GetString()!,out _)&&!TryExtractEvidence(actualDoc.RootElement,actual,actual.GetProperty("profileId").GetString()!,"0",out _); using var missing=JsonDocument.Parse("{\"botPointer\":\"2253593808896\",\"lastShallEndDecisionAction\":9003,\"lastShallEndWrapperActionId\":\"9000\",\"lastGetDecisionAction\":9000,\"lastIsActive\":true}"); negatives=negatives&&!TryReadWrapperEntry(missing.RootElement,actual.GetProperty("botPointerDecimal").GetString()!,9000,out _,out _,out _); var cases=r.GetProperty("cases").EnumerateArray().ToArray();
  bool policy=cases.All(x=>{int incoming=x.GetProperty("incomingActionId").GetInt32(),start=x.GetProperty("startLogicId").GetInt32();bool has=x.GetProperty("hasCurrentAction").GetBoolean(),registered=x.GetProperty("hasRegisteredCurrentAction").GetBoolean();int current=x.GetProperty("currentActionId").GetInt32();bool mismatch=CustomDecisionPolicy.ShouldEndForDifferentCustomAction(incoming,start,has,registered,current);bool finalEnd=incoming<start||!has||mismatch||x.GetProperty("isCurrentActionEnding").GetBoolean();return mismatch==x.GetProperty("expectedMismatch").GetBoolean()&&finalEnd==x.GetProperty("expectedEnd").GetBoolean();});
  var s=File.ReadAllText(Path.Combine(Path.GetFullPath(Path.Combine(sourceRoot,"..","BigBrain")),"Internal","CustomLayerWrapper.cs")); int vanilla=s.IndexOf("if ((int)curDecision.Action < BrainManager.START_LOGIC_ID",StringComparison.Ordinal),nullAction=s.IndexOf("if (customLayer.CurrentAction == null)",StringComparison.Ordinal),mismatch=s.IndexOf("ShouldEndForDifferentCustomAction((int)curDecision.Action",StringComparison.Ordinal),ending=s.IndexOf("if (customLayer.IsCurrentActionEnding())",StringComparison.Ordinal); bool wired=vanilla>=0&&nullAction>vanilla&&mismatch>nullAction&&ending>mismatch&&s.Substring(vanilla,nullAction-vanilla).Contains("return endAction;")&&s.Substring(nullAction,mismatch-nullAction).Contains("return endAction;")&&s.Substring(mismatch,ending-mismatch).Contains("return endAction;")&&s.Substring(ending).Contains("return endAction;");
