 static bool TryReadWrapperEntry(JsonElement e,string bot,int current,out int incoming,out bool ended,out int lastGet)
 {
  incoming=lastGet=0;ended=true; return e.ValueKind==JsonValueKind.Object&&e.TryGetProperty("botPointer",out var bp)&&bp.ToString()==bot&&e.TryGetProperty("lastShallEndDecisionAction",out var d)&&int.TryParse(d.ToString(),out incoming)&&e.TryGetProperty("lastShallEndWrapperActionId",out var c)&&int.TryParse(c.ToString(),out int ci)&&ci==current&&e.TryGetProperty("lastShallEndResult",out var r)&&(r.ValueKind==JsonValueKind.True||r.ValueKind==JsonValueKind.False)&&(ended=r.GetBoolean())==false&&e.TryGetProperty("lastGetDecisionAction",out var g)&&int.TryParse(g.ToString(),out lastGet)&&e.TryGetProperty("lastIsActive",out var a)&&a.ValueKind==JsonValueKind.True;
 }
 static bool TryExtractEvidence(JsonElement root,JsonElement s,out string d)=>TryExtractEvidence(root,s,s.GetProperty("profileId").GetString()!,s.GetProperty("botPointerDecimal").GetString()!,out d);
 static bool TryExtractEvidence(JsonElement root,JsonElement s,string profile,string bot,out string d)
 {
  d="missing QA";var ps=root.GetProperty("result").GetProperty("players").EnumerateArray().Where(x=>x.GetProperty("profileId").GetString()==profile).ToArray();if(ps.Length!=1)return false;var p=ps[0];if(p.GetProperty("botPointer").GetString()!=s.GetProperty("botPointerHex").GetString())return false;
